//! Compiles Blueprint UI files, the GResource bundle and (for development runs)
//! the GSettings schema, so that a plain `cargo run` works without Meson.
//!
//! Icons come from two trees, both generated by `build-aux/make-icons.sh` except the
//! hand-drawn SVGs:
//!
//! - `data/icons/hicolor/`: the app icon theme that Meson installs system-wide. A few
//!   sizes are also bundled here so the tray icon works without an installed theme.
//! - `data/resources/icons/`: icons that are only ever bundled: symbolic action SVGs
//!   and the `lio-branding` logo for the About dialog.
//!
//! Everything lands in the GResource under `/dev/m5ka/Lio/icons/`, which GTK adds to
//! the icon theme search path.

use std::path::{Path, PathBuf};
use std::process::Command;
use std::{env, fs};

const RESOURCE_PREFIX: &str = "/dev/m5ka/Lio";

fn main() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    let resources_dir = manifest_dir.join("data/resources");
    let ui_src = resources_dir.join("ui");
    let ui_out = out_dir.join("ui");

    println!("cargo:rerun-if-changed=data/resources");
    println!("cargo:rerun-if-changed=data/icons");
    println!("cargo:rerun-if-changed=data/dev.m5ka.Lio.gschema.xml");
    for var in [
        "LIO_APP_ID",
        "LIO_PROFILE",
        "LIO_VERSION",
        "LIO_LOCALEDIR",
        "LIO_PKGDATADIR",
        "LIO_GETTEXT_PACKAGE",
        "LIO_BLUEPRINT_COMPILER",
    ] {
        println!("cargo:rerun-if-env-changed={var}");
    }

    compile_blueprints(&manifest_dir, &ui_src, &ui_out);
    let xml = write_gresource_xml(&out_dir, &ui_out, &resources_dir);
    glib_build_tools::compile_resources(
        &[out_dir.to_str().unwrap(), resources_dir.to_str().unwrap()],
        xml.to_str().unwrap(),
        "lio.gresource",
    );
    compile_dev_schema(&manifest_dir, &out_dir);

    // A shared libprojectM looks up `glBindFramebuffer` at run time; export Lio's
    // replacement (src/widgets/milkdrop.rs) so it finds that one before libGL's.
    if env::var("DEP_PROJECTM_LINKAGE").as_deref() == Ok("dynamic") {
        println!("cargo:rustc-link-arg-bins=-Wl,--export-dynamic-symbol=glBindFramebuffer");
    }
}

fn blueprint_compiler(manifest_dir: &Path) -> PathBuf {
    if let Ok(path) = env::var("LIO_BLUEPRINT_COMPILER") {
        return path.into();
    }
    let local = manifest_dir.join(".venv/bin/blueprint-compiler");
    if local.exists() {
        return local;
    }
    "blueprint-compiler".into()
}

fn compile_blueprints(manifest_dir: &Path, ui_src: &Path, ui_out: &Path) {
    let mut files: Vec<PathBuf> = fs::read_dir(ui_src)
        .map(|dir| {
            dir.filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| p.extension().is_some_and(|e| e == "blp"))
                .collect()
        })
        .unwrap_or_default();
    files.sort();
    let _ = fs::remove_dir_all(ui_out);
    fs::create_dir_all(ui_out).unwrap();
    if files.is_empty() {
        return;
    }

    let compiler = blueprint_compiler(manifest_dir);
    let status = Command::new(&compiler)
        .arg("batch-compile")
        .arg(ui_out)
        .arg(ui_src)
        .args(&files)
        .status()
        .unwrap_or_else(|e| {
            panic!(
                "failed to run {} ({e}). Install blueprint-compiler or set LIO_BLUEPRINT_COMPILER",
                compiler.display()
            )
        });
    assert!(status.success(), "blueprint-compiler failed");
}

fn write_gresource_xml(out_dir: &Path, ui_out: &Path, resources_dir: &Path) -> PathBuf {
    let mut entries = Vec::new();
    let mut ui: Vec<_> = fs::read_dir(ui_out)
        .unwrap()
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().into_string().unwrap())
        .filter(|n| n.ends_with(".ui"))
        .collect();
    ui.sort();
    for name in ui {
        entries.push(format!(
            r#"    <file compressed="true" preprocess="xml-stripblanks" alias="ui/{name}">ui/{name}</file>"#
        ));
    }
    if resources_dir.join("style.css").exists() {
        entries.push(r#"    <file compressed="true">style.css</file>"#.to_owned());
    }
    let icons = resources_dir.join("icons");
    if let Ok(dir) = fs::read_dir(&icons) {
        let mut names: Vec<_> = dir
            .filter_map(|e| e.ok())
            .map(|e| e.file_name().into_string().unwrap())
            .filter(|n| n.ends_with(".svg"))
            .collect();
        names.sort();
        for name in names {
            entries.push(format!(
                r#"    <file compressed="true" preprocess="xml-stripblanks" alias="icons/scalable/actions/{name}">icons/{name}</file>"#
            ));
        }
    }
    // Raster icons in the icon-theme layout (`icons/<N>x<N>/apps/*.png`): the About
    // logo from data/resources, and the app icons straight from data/icons (paths are
    // relative to data/resources), so the tray and About work without an installed theme.
    for (dir, path_prefix, sizes) in [
        (
            icons.join("hicolor"),
            "icons/hicolor",
            &["128x128", "256x256"][..],
        ),
        (
            resources_dir.join("../icons/hicolor"),
            "../icons/hicolor",
            &["32x32", "64x64", "128x128", "256x256"][..],
        ),
    ] {
        for size in sizes {
            let Ok(apps) = fs::read_dir(dir.join(size).join("apps")) else {
                continue;
            };
            let mut names: Vec<_> = apps
                .filter_map(|e| e.ok())
                .map(|e| e.file_name().into_string().unwrap())
                .filter(|n| n.ends_with(".png"))
                .collect();
            names.sort();
            for name in names {
                entries.push(format!(
                    r#"    <file alias="icons/{size}/apps/{name}">{path_prefix}/{size}/apps/{name}</file>"#
                ));
            }
        }
    }
    let xml = format!(
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<gresources>\n  <gresource prefix=\"{RESOURCE_PREFIX}\">\n{}\n  </gresource>\n</gresources>\n",
        entries.join("\n")
    );
    let path = out_dir.join("resources.gresource.xml");
    fs::write(&path, xml).unwrap();
    path
}

/// Compiles the schema into `OUT_DIR/schemas`; `config::DEV_SCHEMA_DIR` points there so a
/// non-installed debug build can find its settings.
fn compile_dev_schema(manifest_dir: &Path, out_dir: &Path) {
    let schemas = out_dir.join("schemas");
    fs::create_dir_all(&schemas).unwrap();
    fs::copy(
        manifest_dir.join("data/dev.m5ka.Lio.gschema.xml"),
        schemas.join("dev.m5ka.Lio.gschema.xml"),
    )
    .unwrap();
    let status = Command::new("glib-compile-schemas")
        .arg("--strict")
        .arg(&schemas)
        .status()
        .expect("glib-compile-schemas not found");
    assert!(status.success(), "glib-compile-schemas failed");
    println!("cargo:rustc-env=LIO_DEV_SCHEMA_DIR={}", schemas.display());
}
